class MinQueue {
  constructor(){ this.inbox = []; this.outbox = [] }
  _push(stack, val){ const m = stack.length ? Math.min(val, stack[stack.length - 1].min) : val; stack.push({ val, min: m }) }
  enqueue(x){ this._push(this.inbox, x) }
  dequeue(){ if (!this.outbox.length){ while (this.inbox.length){ const el = this.inbox.pop(); const m = this.outbox.length ? Math.min(el.val, this.outbox[this.outbox.length - 1].min) : el.val; this.outbox.push({ val: el.val, min: m }) } }
